// Helper functions
export function getBusinessesByCategory(categorySlug: string): Business[] {
  const seen = new Set<string>();
  return businesses.filter((b) => {
    if (b.categorySlug !== categorySlug) return false;
    if (seen.has(b.name)) return false;
    seen.add(b.name);
    return true;
  });
}

export function getBusinessesByNeighborhood(neighborhoodSlug: string): Business[] {
  return businesses.filter((b) => b.neighborhoodSlug === neighborhoodSlug);
}

export function getBusinessesByCategoryAndNeighborhood(categorySlug: string, neighborhoodSlug: string): Business[] {
  return businesses.filter((b) => b.categorySlug === categorySlug && b.neighborhoodSlug === neighborhoodSlug);
}

export function getBusinessById(id: string): Business | undefined {
  return businesses.find((b) => b.id === id);
}